package com.media.transcoder.desktop;
import com.fasterxml.jackson.databind.JsonNode; import com.media.transcoder.shared.Json; import javax.swing.*; import javax.swing.filechooser.FileNameExtensionFilter; import javax.swing.table.DefaultTableModel; import java.awt.*; import java.io.*; import java.net.URI; import java.net.http.*; import java.nio.file.*; import java.util.Map; import java.util.HashMap; import java.util.UUID; import java.util.concurrent.CompletableFuture;
public class Dashboard { private final String baseUrl; private final DefaultTableModel model=new DefaultTableModel(new String[]{"ID","Arquivo","Status","Perfis","360p","480p","720p"},0){public boolean isCellEditable(int r,int c){return c>=4;}}; private final JTable table=new JTable(model); private final JLabel message=new JLabel(" "); private volatile boolean sending;
 public Dashboard(String baseUrl){this.baseUrl=baseUrl;}
 public void show(){if(!SwingUtilities.isEventDispatchThread()){SwingUtilities.invokeLater(this::show);return;} JFrame f=new JFrame("Transcoder Video — Conversor local");f.setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);f.setSize(1150,650);f.setLayout(new BorderLayout(10,10));f.add(buildUploadPanel(),BorderLayout.WEST);f.add(new JScrollPane(table),BorderLayout.CENTER);JButton refresh=new JButton("Atualizar jobs");refresh.addActionListener(e->load());f.add(refresh,BorderLayout.SOUTH);for(int i=4;i<7;i++){table.getColumnModel().getColumn(i).setCellRenderer((t,v,s,fc,r,c)->new JButton(v instanceof String x&&!x.isBlank()?"Baixar":""));table.getColumnModel().getColumn(i).setCellEditor(new DownloadEditor(this::download));}f.setVisible(true);load();new Timer(4000,e->load()).start();}
 private JPanel buildUploadPanel(){JPanel p=new JPanel();p.setPreferredSize(new Dimension(320,0));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JButton pick=new JButton("Selecionar vídeo…");JLabel label=new JLabel("Nenhum arquivo selecionado");JComboBox<String> prof=new JComboBox<>(new String[]{"360p","480p","720p"});JTextField origin=new JTextField("Arquivo próprio");JCheckBox consent=new JCheckBox("Confirmo autorização",true);JButton send=new JButton("Enviar e converter");final File[] file={null};pick.addActionListener(e->{JFileChooser c=new JFileChooser();c.setFileFilter(new FileNameExtensionFilter("Vídeos","mp4","mov","mkv","webm","avi","m4v"));if(c.showOpenDialog(p)==JFileChooser.APPROVE_OPTION){file[0]=c.getSelectedFile();label.setText(file[0].getName());}});send.addActionListener(e->{if(sending)return;if(file[0]==null){message.setText("Selecione um vídeo.");return;}if(!consent.isSelected()){message.setText("Confirme a autorização.");return;}sending=true;send.setEnabled(false);sendUpload(file[0],origin.getText(),(String)prof.getSelectedItem(),()->{sending=false;send.setEnabled(true);});});for(Component c:new Component[]{pick,label,new JLabel("Perfil"),prof,new JLabel("Origem"),origin,consent,send}){p.add(c);p.add(Box.createVerticalStrut(8));}return p;}
 private void sendUpload(File file,String source,String profile,Runnable done){CompletableFuture.runAsync(()->{try{String b="----Transcoder"+UUID.randomUUID().toString().replace("-","");ByteArrayOutputStream body=new ByteArrayOutputStream();field(body,b,"origin",source);field(body,b,"permission","Confirmada");field(body,b,"profiles",profile);body.write(("--"+b+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\""+file.getName()+"\"\r\nContent-Type: video/mp4\r\n\r\n").getBytes());Files.copy(file.toPath(),body);body.write(("\r\n--"+b+"--\r\n").getBytes());HttpResponse<String> r=HttpClient.newHttpClient().send(HttpRequest.newBuilder(URI.create(baseUrl+"/videos")).header("Content-Type","multipart/form-data; boundary="+b).POST(HttpRequest.BodyPublishers.ofByteArray(body.toByteArray())).build(),HttpResponse.BodyHandlers.ofString());SwingUtilities.invokeLater(()->message.setText("HTTP "+r.statusCode()));}catch(Exception e){SwingUtilities.invokeLater(()->message.setText("Erro: "+e.getMessage()));}finally{SwingUtilities.invokeLater(done);}});}
 private void field(OutputStream o,String b,String n,String v)throws IOException{o.write(("--"+b+"\r\nContent-Disposition: form-data; name=\""+n+"\"\r\n\r\n"+v+"\r\n").getBytes());}
 private void download(String id){if(id==null||id.isBlank())return;JFileChooser c=new JFileChooser();if(c.showSaveDialog(table)!=JFileChooser.APPROVE_OPTION)return;Path target=c.getSelectedFile().toPath(),tmp=target.resolveSibling(target.getFileName()+".part");HttpClient.newHttpClient().sendAsync(HttpRequest.newBuilder(URI.create(baseUrl+"/arquivos/"+id)).GET().build(),HttpResponse.BodyHandlers.ofFile(tmp)).thenAccept(r->{try{if(r.statusCode()!=200)Files.deleteIfExists(tmp);else Files.move(tmp,target,StandardCopyOption.REPLACE_EXISTING);message.setText("Download HTTP "+r.statusCode());}catch(IOException e){message.setText("Falha: "+e.getMessage());}});}
 private void load(){HttpClient.newHttpClient().sendAsync(HttpRequest.newBuilder(URI.create(baseUrl+"/jobs")).GET().build(),HttpResponse.BodyHandlers.ofString()).thenAccept(r->{try{JsonNode root=Json.MAPPER.readTree(r.body());SwingUtilities.invokeLater(()->{model.setRowCount(0);for(JsonNode j:root){Map<String,String> ids=new HashMap<>();for(JsonNode o:j.path("outputs"))ids.put(o.path("profile").asText(),o.path("id").asText());model.addRow(new Object[]{j.path("id").asText(),j.path("originalName").asText(),j.path("status").asText(),String.join(", ",ids.keySet()),ids.get("360p"),ids.get("480p"),ids.get("720p")});}});}catch(Exception e){message.setText("Falha: "+e.getMessage());}});}
 private static final class DownloadEditor extends DefaultCellEditor{private final JButton b=new JButton("Baixar");private String value;DownloadEditor(java.util.function.Consumer<String>a){super(new JCheckBox());b.addActionListener(e->{a.accept(value);fireEditingStopped();});}public Component getTableCellEditorComponent(JTable t,Object v,boolean s,int r,int c){value=v==null?"":v.toString();b.setEnabled(!value.isBlank());return b;}public Object getCellEditorValue(){return value;}}
}
